function inp(k, d) {
  try {
    const v = $input.get(k);
    return v === undefined || v === null || v === "" ? d : v;
  } catch (e) {
    return d;
  }
}
let fallo = "";
const ambiente = String(inp("ambiente", "")).trim().toLowerCase();
if (ambiente !== "staging" && ambiente !== "production") fallo = "El ambiente debe ser staging o production.";
const authKey = String(inp("authKey", "")).trim();
if (!fallo && (authKey.length < 10 || authKey.includes("{{"))) fallo = "SIN_SESION";
const monto = Number(String(inp("monto", "")).replace(/[^\d.]/g, ""));
if (!fallo && !(monto > 0)) fallo = "MONTO";
const body = { authKey, ambiente, monto };
$context.set("body", JSON.stringify(body));
if (fallo === "SIN_SESION") {
  $output.set("resultado", { ok: true, estado: "sin_sesion", message: "La sesión de Crediviva venció: el cliente debe iniciar sesión otra vez." });
} else if (fallo === "MONTO") {
  $output.set("resultado", { ok: true, estado: "invalido", message: "El ingreso debe ser un número en dólares, ej. 1200." });
} else if (fallo) {
  $output.set("error", { ok: false, estado: "error", code: "CONFIGURACION", message: fallo });
}
$context.set("prepOk", fallo === "SIN_SESION" || fallo === "MONTO" ? "respondido" : fallo ? "no" : "si");

const res = $context.getHttpResponse("fnResponse");
let status = 0;
try {
  status = Number(typeof res?.status === "function" ? res.status() : res?.status) || 0;
} catch (e) {
  status = 0;
}
let data = {};
try {
  data = typeof res?.json === "function" ? await res.json() : (res?.json ?? res?.data ?? {});
} catch (e) {
  data = {};
}
if (typeof data === "string") {
  try { data = JSON.parse(data); } catch (e) { data = {}; }
}
if (!data || typeof data !== "object") data = {};
const ok = status >= 200 && status < 300;
$utils.logger.log("fnResponse", JSON.stringify({ status, estado: data.estado }));
const MENSAJES = {"enlace": "Envía la url al cliente como botón para que complete la verificación en el proveedor.", "aprobado": "La identidad del cliente quedó verificada.", "completado": "Este paso ya estaba completado en Crediviva; continúa con el siguiente.", "bloqueado": "La verificación fue bloqueada por el proveedor.", "reintentar": "El proveedor pide repetir la verificación.", "procesada": "La verificación ya fue procesada; consulta su resultado.", "cliente_existente": "El documento ya pertenece a otro cliente de Crediviva.", "sin_verificacion": "No se encontró una verificación iniciada para este cliente.", "no_lista": "El resultado aún no está listo; vuelve a consultarlo en unos segundos.", "sesion_invalida": "La sesión con el proveedor no es válida; hay que iniciar la verificación de nuevo.", "sin_sesion": "La sesión de Crediviva venció: el cliente debe iniciar sesión otra vez.", "app": "El cliente debe continuar su proceso en la App de Crediviva.", "approved": "Evaluación aprobada.", "manualAnalysis": "La solicitud requiere análisis manual.", "rejected": "La solicitud no cumple los criterios de crédito.", "monto_minimo": "El ingreso mínimo es de $100: pide al cliente que lo revise.", "invalido": "Crediviva no aceptó el dato enviado."};
let salida = "error";
if (ok && typeof data.estado === "string" && data.estado !== "error") {
  salida = "resultado";
  const r = { ok: true, estado: data.estado, message: data.message || MENSAJES[data.estado] || "" };
  for (const k of ["url", "proveedor", "alternativa", "minimo"]) if (data[k] !== undefined) r[k] = data[k];
  $output.set("resultado", r);
} else {
  $output.set("error", { ok: false, estado: "error", code: "HTTP_" + status, message: "El servicio de Crediviva no respondió." });
}
$context.set("salida", salida);

$output.set("error", {
  ok: false,
  estado: "error",
  code: "TECNICO",
  message: "No fue posible comunicarse con el servicio de Crediviva.",
});
